return [
  {
    json: {
      design_id: 'DOG-0001',
      status: 'QC Approved',
      niche: 'Hundebesitzer',
      target_group: 'Hundemama',
      occasion: 'Geburtstag',
      claim: 'Gassi ist mein Cardio',
      main_keyword: 'hundemama shirt',
      product: 'Unisex T-Shirt',
      pod_provider: 'Printify',
      design_file_url: 'https://example.com/design.png',
      mockup_file_url: 'https://example.com/mockup.png'
    }
  }
];

const item = $json;

const title = `${item.target_group} Shirt ${item.claim}, Geschenk fuer ${item.target_group}, ${item.product}`;
const tags = [
  item.main_keyword,
  'hundeliebe',
  'gassi shirt',
  'hunde geschenk',
  'shirt frau',
  'lustiges shirt',
  'hundebesitzer',
  'pfoten shirt',
  'geschenk frau',
  'hunde mama',
  't shirt hund',
  'haustier shirt',
  'cardio shirt'
];

return [{
  json: {
    ...item,
    etsy_title: title,
    etsy_tags: tags.join(','),
    etsy_description: `Lustiges ${item.product} fuer ${item.target_group}. Das Produkt wird erst nach Bestellung produziert. Bitte Groessentabelle und Varianten pruefen.`,
    qc_required_before_publish: true
  }
}];

const required = ['design_id', 'claim', 'design_file_url', 'mockup_file_url', 'etsy_title', 'etsy_tags', 'etsy_description'];
const missing = required.filter((key) => !$json[key]);

if (missing.length) {
  return [{ json: { ...$json, automation_status: 'FAILED_VALIDATION', missing_fields: missing.join(',') } }];
}

const forbiddenHints = ['disney', 'nike', 'adidas', 'star wars', 'harry potter', 'pokemon', 'fifa'];
const haystack = `${$json.claim} ${$json.etsy_title} ${$json.etsy_tags} ${$json.etsy_description}`.toLowerCase();
const matched = forbiddenHints.filter((term) => haystack.includes(term));

if (matched.length) {
  return [{ json: { ...$json, automation_status: 'FAILED_FORBIDDEN_HINT', forbidden_hints: matched.join(',') } }];
}

return [{ json: { ...$json, automation_status: 'READY_FOR_DRAFT_CREATION' } }];

return [{
  json: {
    ...$json,
    printify_payload_preview: {
      title: $json.etsy_title,
      description: $json.etsy_description,
      tags: $json.etsy_tags,
      images: [$json.design_file_url, $json.mockup_file_url],
      publish: false
    },
    next_manual_step: 'Create Printify/Etsy draft, inspect preview, then publish manually if QC passes.'
  }
}];
